#nullable enable // autogenerated  

using MVZ2.GameContent.Seeds;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Level;

namespace MVZ2.GameContent.Stages
{
    [AutoStageDefinition(VanillaStageNames.BombingZone)]
    public partial class BombingZone : StageDefinition
    {
        public BombingZone(string nsp, string name) : base(nsp, name)
        {
            AddBehaviour(new WaveStageBehaviour(this));
            AddBehaviour(new BombingZoneStageBehaviour(this));
        }
        public override void OnStart(LevelEngine level)
        {
            base.OnStart(level);
            var blueprints = new NamespaceID[]
            {
                VanillaBlueprintID.heavyWeaponFlashbang,
                VanillaBlueprintID.heavyWeaponRapid,
                VanillaBlueprintID.heavyWeaponSpread,
            };
            level.SetSeedSlotCount(blueprints.Length);
            level.FillSeedPacks(blueprints);
        }
    }
}
